export type $defs = Record<string, never>;

export type external = Record<string, never>;

export interface operations {

  /**
   * Get a public JavaScript extension file
   * @description Serves JavaScript files for public extensions. Only .js files are supported.
   */
  getPublicJsExtensionFile: {
    parameters: {
      path: {
        /** @description The extension type/package ID (e.g., io.forcerefresh.layout.object) */
        type: string;
        /** @description Semantic version of the extension */
        version: string;
        /** @description The JavaScript filename (must end with .js) */
        filename: string;
      };
    };
    responses: {
      /** @description The requested JavaScript file */
      200: {
        headers: {
          "Content-Type"?: string;
          "Cache-Control"?: string;
        };
        content: {
          "application/javascript": string;
        };
      };
      /** @description Invalid request - only .js files are supported */
      400: {
        content: {
          "application/json": {
            error?: string;
            requestedFile?: string;
            supportedFormats?: string[];
          };
        };
      };
      /** @description JavaScript file not found */
      404: {
        content: {
          "application/json": {
            error?: string;
            path?: string;
            type?: string;
            version?: string;
            filename?: string;
          };
        };
      };
    };
  };
}
